-- composition of rule kernels duplicate_groups x projection_pullup (duckdb), template product
SELECT count(*) FROM (SELECT 10::bigint AS c0 EXCEPT SELECT 10::bigint AS c0 FROM t4 AS a1 GROUP BY a1.c1, a1.c0, a1.c3) AS ka CROSS JOIN (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, [1, 2, 3]::int[] AS c1, ((CASE WHEN REGEXP_MATCHES (((a1.c5 || a1.c5) || a1.c5), '[0-9]{2}') THEN 0.0::numeric ELSE CASE WHEN (FALSE OR CASE WHEN TRUE THEN TRUE ELSE FALSE END) THEN 2.25::numeric ELSE (SELECT MIN (0.0::numeric) FROM rc AS a2) END END % 100) * ((a1.c0)::numeric % 100)) AS c2, LEAST (LEAST (1.5::numeric, (SELECT MAX (100.0::numeric) FROM v0 AS a3 WHERE a1.c1)), NULL::numeric) AS c3 FROM t3 AS a1 WHERE FALSE) AS kb;
